/bin/bash -lc "python3 - <<'PY'
import ast
import copy
import hashlib
import json
from pathlib import Path
runtime=json.loads(Path('runtime.json').read_text())
p=json.loads(Path('proposal.json').read_text())
def validate(value,schema,path='"'$'"'):
    kinds={'object':dict,'array':list,'string':str,'boolean':bool,'number':(int,float),'integer':int}
    if 'type' in schema:
        assert isinstance(value,kinds[schema['type']]), (path,'type')
    if 'const' in schema: assert value==schema['const'],(path,'const')
    if 'enum' in schema: assert value in schema['enum'],(path,'enum')
    if isinstance(value,dict):
        assert set(schema.get('required',[]))<=set(value),(path,'required')
        props=schema.get('properties',{})
        if schema.get('additionalProperties') is False:
            assert set(value)<=set(props),(path,'additionalProperties')
        for key,val in value.items():
            if key in props: validate(val,props[key],path+'.'+key)
    if isinstance(value,list):
        assert len(value)>=schema.get('minItems',0),(path,'minItems')
        if 'items' in schema:
            for i,val in enumerate(value):validate(val,schema['items'],path+f'[{i}]')
    if isinstance(value,str):assert len(value)>=schema.get('minLength',0),(path,'minLength')
validate(p['study'],runtime['study_schema'])
assert set(p)=={'study','parent_trial','variants'}
assert p['study']['protocol_ref']==runtime['required_study_protocol_ref']
assert p['parent_trial'] in {h['id'] for h in runtime['context']['history']}
assert 1<=len(p['variants'])<=4
assert any(v['role']=='candidate' for v in p['variants'])
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
base=ast.parse(Path('baseline_reference.py').read_text())
base_class=next(n for n in base.body if isinstance(n,ast.ClassDef))
base_methods={n.name:n for n in base_class.body if isinstance(n,ast.FunctionDef)}
allowed={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib'}
normalized=[]
for v in p['variants']:
    assert set(v)=={'name','file','role','config','note'}
    assert v['role'] in {'candidate','control'}
    assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
    source=Path(v['file']).read_text()
    compile(source,v['file'],'exec')
    tree=ast.parse(source)
    for n in ast.walk(tree):
        if isinstance(n,ast.Import):
            assert all(alias.name.split('.')[0] in allowed for alias in n.names)
        elif isinstance(n,ast.ImportFrom):assert n.module.split('.')[0] in allowed
        elif isinstance(n,ast.Call) and isinstance(n.func,ast.Name):assert n.func.id not in {'eval','exec','open','__import__','compile','input'}
    config=ast.literal_eval(next(n.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets)))
    assert config==v['config']
    klass=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
    methods={n.name:n for n in klass.body if isinstance(n,ast.FunctionDef)}
    assert {'__init__','forward','diagnostics','evidence_counts','evidence_features'}<=set(methods)
    init=copy.deepcopy(methods['__init__'])
    assert len(init.body)==len(base_methods['__init__'].body)+2
    init.body=init.body[:-2]
    assert ast.dump(init,include_attributes=False)==ast.dump(base_methods['__init__'],include_attributes=False),'reference initialization altered'
    forward=copy.deepcopy(methods['forward'])
    forward.body=forward.body[:-3]+[copy.deepcopy(base_methods['forward'].body[-1])]
    assert ast.dump(forward,include_attributes=False)==ast.dump(base_methods['forward'],include_attributes=False),'reference forward altered'
    for n in tree.body:
        if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets):
            n.value=ast.Constant(value='factorial flags normalized')
    normalized.append(ast.dump(tree,include_attributes=False))
    digest=hashlib.sha256(Path(v['file']).read_bytes()).hexdigest()
    assert digest in v['note']
    print(v['file']+': syntax, numeric-import boundary, CONFIG, reference-preservation and source hash OK')
assert len(set(normalized))==1,'variants contain differences beyond CONFIG'
assert {(v['config']['target_match'],v['config']['separate_actions']) for v in p['variants']}=={(True,True),(False,True),(True,False),(False,False)}
expected='ee10868f589c077b19f57a1fb07702c947c56e970994cdc537ef83ea2b8bc943'
for filename in ('baseline_reference.py','history_baseline_static.py','history_baseline_pooled.py','history_baseline_din.py'):
    assert hashlib.sha256(Path(filename).read_bytes()).hexdigest()==expected,filename
print('Study schema, variant contract, full factorial, and read-only ancestor source hashes OK.')
print('Forward shapes reviewed: counts [B,4,2,4] -> features [B,32] -> residual [B]; parent logits [B].')
print('No numerical model execution, training, held-out assessment, installations, or unapproved artifact writes.')
p['study']['evidence_refs'].append('Local source checks completed: study_schema recursively checked with standard-library validator; four modules compile; imports restricted to numeric allowlist; CONFIG agrees with proposal; complete 2x2 cells; variant ASTs differ only in literal CONFIG; reference initializer and forward ASTs preserved except appended residual; source hashes and read-only ancestor hashes verified. Torch numerical execution remains unavailable.')
Path('proposal.json').write_text(json.dumps(p,indent=2)+'\\n')
PY"

